<?php/** * Description of User * * @author Suharshana DsW * @web www.nysc.lk */class Subcategory {    public $id;    public $entr_sub_category;    public $name;    public function __construct($id) {        if ($id) {            $query = "SELECT `id`,`entr_sub_category`,`name` FROM `entr_sub_category` WHERE `id`=" . $id;            $db = new Database();            $result = mysqli_fetch_array($db->readQuery($query));            $this->id = $result['id'];            $this->name = $result['entr_sub_category'];            $this->name = $result['name'];            return $result;        }    }    public function create() {        $query = "INSERT INTO `entr_sub_category` (`name`) VALUES  ('"                . $this->name . "')";        $db = new Database();        $result = $db->readQuery($query);        if ($result) {            return TRUE;        } else {            return FALSE;        }    }    public function all() {        $query = "SELECT * FROM `entr_sub_category`";        $db = new Database();        $result = $db->readQuery($query);        $array_res = array();        while ($row = mysqli_fetch_array($result)) {            array_push($array_res, $row);        }        return $array_res;    }    public function delete() {        $query = 'DELETE FROM `entr_sub_category` WHERE id="' . $this->id . '"';        $db = new Database();        return $db->readQuery($query);    }     public function GetSubByCategory($category) {        $query = "SELECT * FROM `entr_sub_category` WHERE `category` = '" . $category . "'";        $db = new Database();        $result = $db->readQuery($query);        $array_res = array();        while ($row = mysqli_fetch_array($result)) {            array_push($array_res, $row);        }        return $array_res;    }    }